#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#define _cleanup_(x)
#define eprintf(...) fprintf(stderr,__VA_ARGS__)
static int added,groups;
static int fdupes_dedupe(void){groups++;return 0;}
static void free_all_filerecs(void){}
static void add_file_fdupes(char *p){added++;}
static int process_fdupes(void)
{
	int ret = 0;
	_cleanup_(freep) char *path = NULL;
	size_t pathlen = 0;
	ssize_t readlen;

	while ((readlen = getline(&path, &pathlen, stdin)) != -1) {
		if (readlen == 0)
			continue;

		if (readlen == 1 && path[0] == '\n') {
			ret = fdupes_dedupe();
			if (ret)
				return ret;
			free_all_filerecs();
			continue;
		}

		if (readlen > 0 && path[readlen - 1] == '\n') {
			path[--readlen] = '\0';
		}

		if (readlen > PATH_MAX - 1) {
			eprintf("Path max exceeded: %s\n", path);
			continue;
		}

		add_file_fdupes(path);
	}

	return 0;
}
int main(void){int r=process_fdupes();printf("added=%d groups_processed=%d return=%d\n",added,groups,r);return r;}
